let p = msg.payload;
if (typeof p === 'string') {
  try { p = JSON.parse(p); } catch(e) { /* leave as string */ }
}
msg.headers = { 'Content-Type': 'application/json' };
msg.payload = {
  variable: p.sensor_type || p.variable,
  sensor: p.device_id || p.sensor,
  value: p.value,
  timestamp: p.timestamp || new Date().toISOString()
};
return msg;

// Define thresholds for each sensor
const thresholds = {
    temperature: { low_warn: 14, low_crit: 10, high_warn: 30, high_crit: 35 },
    humidity: { low_warn: 40, low_crit: 30, high_warn: 80, high_crit: 90 },
    soil_moisture: { low_warn: 30, low_crit: 20, high_warn: 80, high_crit: 90 },
    co2: { low_warn: 350, high_warn: 1200, high_crit: 2000, extreme: 3000 }
};

let p = msg.payload;

// If payload is a string, try to parse it as JSON
if (typeof p === 'string') {
    try {
        p = JSON.parse(p);
    } catch (e) {
        return null;
    }
}

let alert = null;

// Detect alert based on sensor type and thresholds
switch (p.sensor_type) {
    case 'temperature':
        if (p.value < thresholds.temperature.low_crit) alert = { event_type: 'under_limit', urgency: 'high' };
        else if (p.value < thresholds.temperature.low_warn) alert = { event_type: 'warning_bottom', urgency: 'medium' };
        else if (p.value > thresholds.temperature.high_crit) alert = { event_type: 'over_limit', urgency: 'high' };
        else if (p.value > thresholds.temperature.high_warn) alert = { event_type: 'warning_top', urgency: 'medium' };
        break;
    case 'humidity':
        if (p.value < thresholds.humidity.low_crit) alert = { event_type: 'under_limit', urgency: 'high' };
        else if (p.value < thresholds.humidity.low_warn) alert = { event_type: 'warning_bottom', urgency: 'medium' };
        else if (p.value > thresholds.humidity.high_crit) alert = { event_type: 'over_limit', urgency: 'high' };
        else if (p.value > thresholds.humidity.high_warn) alert = { event_type: 'warning_top', urgency: 'medium' };
        break;
    case 'soil_moisture':
        if (p.value < thresholds.soil_moisture.low_crit) alert = { event_type: 'under_limit', urgency: 'high' };
        else if (p.value < thresholds.soil_moisture.low_warn) alert = { event_type: 'warning_bottom', urgency: 'medium' };
        else if (p.value > thresholds.soil_moisture.high_crit) alert = { event_type: 'over_limit', urgency: 'high' };
        else if (p.value > thresholds.soil_moisture.high_warn) alert = { event_type: 'warning_top', urgency: 'medium' };
        break;
    case 'co2':
        if (p.value > thresholds.co2.extreme) alert = { event_type: 'over_limit', urgency: 'high' };
        else if (p.value > thresholds.co2.high_crit) alert = { event_type: 'over_limit', urgency: 'high' };
        else if (p.value > thresholds.co2.high_warn) alert = { event_type: 'warning_top', urgency: 'medium' };
        else if (p.value < thresholds.co2.low_warn) alert = { event_type: 'warning_bottom', urgency: 'medium' };
        break;
}

// If alert detected, create payload for /api/events POST
if (alert) {
    msg.headers = { 'Content-Type': 'application/json' };
    msg.payload = {
        sensor: p.device_id,
        variable: p.sensor_type,
        event_type: alert.event_type,
        urgency: alert.urgency,
        status: 'active',
        creation_date: new Date().toISOString()
    };
    return [msg];
}

// If no alert, do nothing
return null;
